L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT5_INTERLUDE3"
L38_1 = "Le monde nous exhorte à donner du sens à nos vies. Mais personne ne nous dit que ce sens peut être trouvé au plus profond de nous-mêmes."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT2_INTERLUDE2"
L39_1 = "Le Monastère de Valentinus est un lieu de culte pour les fidèles qui ont embrassé l'idéologie de la Société. Ils sont convaincus que la rencontre d'une entité transcendante exempte des contraintes de la réalité, également connue sous le nom de Lac de la connaissance, les guidera vers la vérité.\nMais peu à peu, le courant a fini par tourner et le monastère a perdu son emprise. Bientôt, les ascètes concentrèrent davantage leurs efforts à l'observation et la capture d'êtres mystiques et transcendant, au-delà de l'entendement."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_ESPR2_6_1"
L40_1 = "L'arbitre"
