L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP9_5_ACT4_INTERLUDE_1"
L42_1 = "FRC signifie Force de Réalité Contraire. En d'autre terme, elle désigne le potentiel humain d'un individu.\nLes Counters possèdent un pouvoir prodigieux, mais ils ne savent pas l'utiliser. Au lieu de ça, ils le gaspillent tout au long de leur vie."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_2_2"
L43_1 = "Un bon Counter doit savoir maîtriser ses émotions. Les troubles psychologiques découlant de l'excitation sont la cause principale qui empêche certains d'entre eux à contrôler correctement leur FRC. Parfois, il suffit juste de savoir garder son calme pour être plus fort."
L41_1[1] = L42_1
L41_1[2] = L43_1
