L45_1 = "SI_UNIT_SKILL_DESC_MILITIA_C_SCISSOR_HYPER_LV1"
L46_1 = "Charge rapidement vers l'avant, infligeant des dégâts de zone dans un large périmètre. Inflige des dégâts supplémentaires égaux à 25 % des PV actuels (15 % en compétition) aux cibles touchées (à l'exception des boss)."
L44_1[1] = L45_1
L44_1[2] = L46_1
