L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_SKIN_DESC_NKM_UNIT_GEASS_M_LANCELOT_LIMITED"
L9_1 = "<color=#ffd34c>※ L'armure de combat reste inchangée.</color>\n\nLes Chevaliers Noirs comptent une jeune fille bien énigmatique dans leurs rangs.\nEt bien que des rumeurs circulent à son sujet, elle ne semble pas vraiment y prêter attention.\nEst-ce cette même indifférence qui la pousse à revêtir cet uniforme si sombre ? Ou bien juste un caprice de sa part ?\n\n<color=#ffd34c>Sais-tu pourquoi la neige est blanche ? Parce qu'elle a oublié de quelle couleur elle était.</color>"
L7_1[1] = L8_1
