L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_SKIN_DESC_NKM_UNIT_HARMONY_C_VIOLIN_SUMMER"
L4_1 = "Une station balnéaire aux couleurs de l'été,\net une musicienne errante de talent.\nQuel meilleur décor pour dérouler un répertoire sensuel et virtuose ?\nVous aussi, faites-vous capturer par ce spectacle enchanteur.\n\n<color=#ffd34c>C'est toi, mon manager ? Prépare la scène et les instruments, tu veux bien ?</color>"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_1_1"
L5_1 = "Le requiem de l'apocalypse résonne aux quatre coins du monde.\nCeux qui avaient juré de protéger le monde ce sont retournés contre lui. Leur volonté a survécu, mais elle a été viciée à jamais.\n\n<color = # ffd34c>※ Ceci est un donjon d'évènement qui ne peut être effectué qu'avec les unités prédéployées.<color=#ffd34c>"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_HARMONY_CA_CONDUCT"
L6_1 = "Un cadre à l'effigie d'une cheffe d'orchestre capable d'harmoniser les tonalités les plus fortes. Équipez-le dans votre profil pour afficher la puissance de votre entreprise."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_EVENT_PASS_14"
L7_1 = "Un cadre modélisé d'après l'armure de ceux qui se battent au front pour expier leurs péchés. Équipez-le dans votre profil pour afficher la puissance de votre entreprise."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_CARNIVAL_1_1_HM"
L8_1 = "Un jour comme les autres au pays"
