L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_UNIT_DESC_NKM_UNIT_HARMONY_C_BASS"
L9_1 = "Une soigneuse au sol à distance qui soigne ses alliés sur la durée"
L7_1[1] = L8_1
L7_1[2] = L9_1
