L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_ACT5_1_2"
L43_1 = "La Milice est constituée de spécialistes des tactiques anti-Counter.\n\n<color=#ffd34c>※ [Lee Yuri] : gagne un bonus d'ATQ chaque fois qu'un camarade meurt.\nUtilise sa compétence ultime chaque fois que le bonus est cumulé 4 fois.\n※ [Kang Minwoo] : réduit les DGT subis par ses camarades Counters.\nLance un bonus de récupération de PV sur ses camarades chaque fois que l'un d'entre eux meurt.</color>"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_ACT5_1_3"
L44_1 = "La Milice est constituée de spécialistes des tactiques anti-Counter.\n\n<color=#ffd34c>※ [Lee Yuri] : gagne un bonus d'ATQ chaque fois qu'un camarade meurt.\nUtilise sa compétence ultime chaque fois que le bonus est cumulé 4 fois.\n※ [Kang Minwoo] : réduit les DGT subis par ses camarades Counters.\nLance un bonus de récupération de PV sur ses camarades chaque fois que l'un d'entre eux meurt.\n※ [Choi Jihoon] : gagne un bonus de VIT ATQ chaque fois qu'un camarade meurt.\nLes attaques de base retirent 1 cumul du bonus.</color>"
