L44_1 = "SI_SKIN_DESC_NKM_UNIT_C_JOO_SHI_YOON_AP_SUMMER"
L45_1 = "La menace des objets corrompus ne nous laisse aucun répit pendant les vacances d'été.\nLes hôtels les plus luxueux rivalisent donc d'attentions pour les Counters qu'ils accueillent.\nLa présence d'un Counter dans un établissement rassure les autres clients.\n\n<color=#ffd34c>Je ne comptais pas rester longtemps, mais puisque vous insistez…</color>"
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP6_1_2"
L46_1 = "La FRC est le principal atout des Counters. Il leur suffit d'une part infime de FRC pour contrer les effets des rayons de corruption émis par les O.C. et utiliser leur arme à son plein potentiel."
L44_1[1] = L45_1
L44_1[2] = L46_1
