L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DAMAGE_2"
L6_1 = "Ceci est un message de la Direction.\nL'appareil d'entraînement conçu par notre généreux président a été amélioré. Une fois encore, les équipes présentant des résultats prometteurs lors des simulations seront modestement récompensées. Nous vous remercions de votre participation.\n\n<color=#FFCF3B>Détruisez la cible en 1 minute. Les unités à forte puissance de feu sont recommandées.</color>"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DAMAGE_5"
L7_1 = "Ceci est un message de la Direction.\nNotre honorable président a mis à disposition un nouvel appareil d'entraînement différent du modèle que vous connaissez. Agents de terrain, nous vous souhaitons bonne chance. Merci de laisser les pièces à leur place. Elles sont peintes à la bombe et non à la feuille d'or.\n\n<color=#FFCF3B>Détruisez la cible en 1 minute. Les unités à forte puissance de feu sont recommandées.</color>"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DAMAGE_1"
L8_1 = "Ceci est un message de la Direction.\nNotre généreux président a conçu un appareil d'entraînement destiné à motiver les agents de terrain en les aidant à améliorer leurs performances. Montez une équipe et simulez une bataille contre la machine. Les équipes aux résultats prometteurs seront récompensées.\n\n<color=#FFCF3B>Détruisez la cible en 1 minute. Les unités à forte puissance de feu sont recommandées.</color>"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DAMAGE_6"
L9_1 = "Ceci est un message de la Direction.\nNotre président charismatique a accompli un véritable miracle ! Ce tout nouvel appareil agira telle une arme de capitalisme sanctionnant les employés ramollis. Agents de terrain, ne vous lancez dans une bataille de simulation que si vous avez foi en vos compétences de combat.\n\n<color=#FFCF3B>Détruisez la cible en 1 minute. Les unités à forte puissance de feu sont recommandées.</color>"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DAMAGE_4"
L10_1 = "Ceci est un message de la Direction.\nNotre président, honnête contribuable, a témoigné un vif intérêt à l'égard des résultats de vos récentes simulations. Par ailleurs, veuillez noter que la rumeur selon laquelle l'appareil d'entraînement serait fait de pièces de remplacement provenant du hangar est purement infondée.\n\n<color=#FFCF3B>Détruisez la cible en 1 minute. Les unités à forte puissance de feu sont recommandées.</color>"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DAMAGE_3"
L11_1 = "Ceci est un message de la Direction.\nUne nouvelle arme haute performance a été ajoutée à l'appareil d'entraînement conçu par notre formidable président. Les équipes présentant des résultats prometteurs lors des simulations seront gracieusement récompensées. Nous vous remercions de votre participation.\n\n<color=#FFCF3B>Détruisez la cible en 1 minute. Les unités à forte puissance de feu sont recommandées.</color>"
L9_1[1] = L10_1
L9_1[2] = L11_1
