L10_1 = "SI_SKIN_DESC_NKM_UNIT_C_HB_GAEUN_NEWYEAR2021"
L11_1 = "Elle approche à la lueur du petit jour, faisant crisser la neige sous ses pas,\nporteuse d'une fabuleuse nouvelle.\nSes joues, rosies par le froid et l'excitation\net le fin sourire sur son visage signent la promesse d'une nouvelle aube.\n\n<color=#ffd34c>Tout de suite : l'émission spéciale Nouvel An de HRT Berry. Vive Berry !</color>"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EVENT_ADMIN_2_1"
L12_1 = "Elle se souciait plus du nombre de boulets de canon qu'il lui restait que de l'intervalle entre ceux-ci."
