L32_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SIGMA_1_3"
L33_1 = "Les humains ont créé une myriade d'entités qui nécessitent un contrôle extérieur.\nEt personne ne leur a appris quoi faire une fois libres de leurs actes.\n\n<color=#ffd34c>Dans ce niveau, l'IA thalamus combat en solitaire dans le Contremonde.</color>\n<color=#ffd34c>Le drone de soutien soigne les alliés et perturbe les O.C., diminuant les dégâts qu'ils infligent.</color>"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
