L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_DP_BASE_SUB_MENU_DETAIL_PERSONNEL"
L35_1 = "Les ressources humaines sont la clé de la réussite. Le bureau du PDG encourage efficacité et productivité en réalisant\ndes évaluations internes basées sur les critères de performance de l'Administration. Mais c'est vous qui décidez, M. le Président."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_STREGA_1_2"
L36_1 = "Les langues des humains sont un miroir de leurs cultures."
