L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_SKIN_DESC_NKM_UNIT_C_FALLEN_ROSARIA_SUMMER"
L37_1 = "Les émotions humaines sont toujours très intéressantes à observer,\net elles abondent dans les lieux de vacances d'été comme celui-ci.\nJe vois passer un triangle amoureux…\nEuh, Seigneur Sombre, qu'est-ce que vous regardez ?\n\n<color=#ffd34c>Je ne vais pas pouvoir finir ce granité toute seule. Vous voulez venir et m'aider ?</color>"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
