L19_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_BG_MILITIA"
L20_1 = "Même la plus somptueuse des villes cache une part sombre.\nCette ruelle, par exemple, dans laquelle nombre de crimes sont commis au quotidien sans que personne ne les remarque.\nPeut faire office d'arrière-plan pour le salon."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
