L24_1 = "SI_UNIT_SKILL_DESC_M_RAS_TOWER_ATTACK_LV1"
L25_1 = "Elle active le système d'autodéfense thalamus. Elle concentre l'énergie environnante et fait feu, infligeant des dégâts de zone."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_UNIT_SKILL_DESC_M_FUTURE_HARPY_PASSIVE_LV1"
L26_1 = "En cas d'urgence, il active son système de transformation. Lorsqu'il se déploie, sa DÉF est réduite de 90 %. Cependant, lorsque ses PV atteignent 50 % ou moins, il se transforme en une unité de défense au sol avec une pleine DÉF, mais 50 % de moins en ATQ et en CRIT."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_SHIP_SKILL_DESC_X_AHAB_HYPER1"
L27_1 = "Actionne une turbine spéciale qui projette de l'air comprimé et renverse avec force les ennemis qui se trouvent devant en leur infligeant des dégâts de zone. Les ennemis perdent 80 % de VIT pendant 10 secondes. Érige une barrière inamovible de 20 % des PV max autour du vaisseau."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_SHIP_SKILL_DESC_X_AHAB_HYPER1_LV2"
L28_1 = "Actionne une turbine spéciale qui projette efficacement de l'air comprimé et renverse avec force les ennemis qui se trouvent devant en leur infligeant des dégâts de zone. Les ennemis perdent 80 % de VIT pendant 10 secondes. Érige une barrière inamovible de 20 % des PV max autour du vaisseau, et octroie +10 % de VIT ATQ à tous les alliés aussi longtemps que cette barrière est active."
L26_1[1] = L27_1
L26_1[2] = L28_1
