L48_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_1_DESC_01"
L49_1 = "En combat stratégique, vous pouvez <COLOR=#FFBC00>participer à des batailles asynchrones</COLOR>.\nVous combattrez <COLOR=#FFBC00>d'autres escouades défensives</COLOR>.\nEn cas de victoire, vous obtenez des points de victoire, mais en cas de défaite, vous les perdez."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_DESC_01"
L50_1 = "Pour rejoindre un combat stratégique, vous devez tout d'abord <COLOR=#FFBC00>former une escouade défensive</COLOR>.\nVotre escouade défensive repoussera les attaques d'autres compagnies et les bonus ainsi que les unités bannies et avantagées seront appliqués.\nVous recevrez des <COLOR=#FFBC00>points de compétition</COLOR> après chaque victoire en défense.\nEn cas de défaite, vos points de victoire diminueront jusqu'à une certaine limite."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
