L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_HYPER_LV1"
L13_1 = "Lance le Sergent Smith dans les airs et demande une assistance armée. Utilise une mitrailleuse reçue au moment opportun et inflige des dégâts 3 fois à l'avant sur une distance de 800, 1000 et 1200 pour un total de 9 fois."
L11_1[1] = L12_1
L11_1[2] = L13_1
