L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR_GET_01"
L11_1 = "Roulement de tambour... Tadaa ! La traqueuse prête à tout pour éradiquer le mal à travers le monde, Raphaela Julie est dans la place ! Laissez-moi faire !"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR_LOBBY_CAPTAIN"
L12_1 = "OOooh ! Tu m'as enfin remarquée !"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR_LOBBY_CONNECT"
L13_1 = "C'est Jun qui m'a parlé de toi. Tu es le fameux Michael le Rapace de l'Enfer ! Hein ? Non ?"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR_LOBBY_CONNECT_LIFETIME"
L14_1 = "C'est la tête de champignon qui me l'a dit. En fait tu.... Tu es le premier Counter Masqué !... C'est pas ça non plus ?"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR_LOBBY_TOUCH_NORMAL_1"
L15_1 = "Ça ressemble un peu à une technique d'escrime immobile mais en fait c'est complètement différent. Je veux dire par là que ma méthode de traque à la lance n'a rien à voir avec ce maniement d'épée de pacotille. Hé hé."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR_LOBBY_TOUCH_NORMAL_2"
L16_1 = "Cronenworth ? Ah ! Je sais. La capitaine nous détestait plus que tout. On leur piquait toujours leur public. On est allés les voir en cachette avec Jun... C'était franchement glauque."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_C_SPEAR_LOBBY_TOUCH_NORMAL_3"
L17_1 = "Jun et moi, on s'occupe toujours du début et de la fin des spectacles. Après tout, rien de mieux qu'une belle danse sophistiquée pour garder l'attention du public."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
