L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_OZ_1_1"
L30_1 = "Je n'ai jamais cessé de regarder les informations à la télévision et dans les journaux. Mais avec le temps, on parlait de moins en moins de toi. Mais j'ai continué à penser à toi tous les jours, pour ne pas t'oublier."
L28_1[1] = L29_1
