L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_OZ_1_INTERLUDE_2"
L31_1 = "Une fois, j'ai rêvé de nos retrouvailles... Mais encore une fois, j'ai été très froide avec toi. Peut-être parce que je ne suis pas prête à te revoir dans cet état."
L29_1[1] = L30_1
