L6_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCAVENGER_S_CUTLASS@AB_UI_UNIT_VOICE_NKM_UNIT_SCAVENGER_S_CUTLASS_LOBBY_TOUCH_NORMAL_3"
L7_1 = "L'éternium est vraiment le matériau parfait pour faire des expériences. On devrait en prendre plus, et tout garder pour nous."
