L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCAVENGER_S_CUTLASS@AB_UI_UNIT_VOICE_NKM_UNIT_SCAVENGER_S_CUTLASS_LOBBY_TOUCH_NORMAL_4"
