L1_1 = {}
L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_PHASE_EVENT_HORIZON_1_CM"
L3_1 = "Jehuty Biotech a déployé de nombreux efforts afin d'améliorer son image.\nIls ont, par exemple, agrandi les étages inférieurs pour installer des salles de classes où les visiteurs peuvent en apprendre davantage sur la bio-ingénierie."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_PHASE_EVENT_HORIZON_2_CM"
L4_1 = "Les étages intermédiaires du Quartier général constituaient l'épine dorsale de l'entreprise, responsable de la gestion des bureaux et des centres de recherches dans le monde entier.\nCependant, les employés de ces étages se sont souvent plaints que l'ascenseur géant menant directement du sous-sol aux étages supérieurs prenait trop de place et les gênait dans leur travail. "
L2_1[1] = L3_1
L2_1[2] = L4_1
