L2_1 = "SI_EPISODE_DESC_1_SS_ORCA"
L3_1 = "Lors d'une mission de reconnaissance comme toutes les autres, le mercenaire vétéran Eddie Fisher croise la route d'un Counter connu sous le nom de légende urbaine. Contrairement à la rumeur, Orca n'est en réalité qu'une petite fille..."
L1_1[1] = L2_1
