L2_1 = {}
L3_1 = "SI_EPISODE_DESC_1_SS_POLICE"
L4_1 = "Le SWAT 4 est une unité spéciale de lutte contre les Counters criminels, qui ne comptait qu'une seule membre jusqu'au jour où une supérieure sans expérience y est soudain affectée. Le même jour, une affaire colossale défraye la chronique..."
L2_1[1] = L3_1
