L3_1 = {}
L4_1 = "SI_EPISODE_DESC_1_SS_SHADE"
L5_1 = "Une prêteuse à gage boit seule à la table d'un bar désert. Elle se plonge dans ses souvenirs, et dans les affres du passé..."
