L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_SKIN_DESC_NKM_UNIT_C_HB_GAEUN_CASUAL"
L20_1 = "Aujourd'hui, je vous présente une tenue spéciale proposée par les membres !\nAvec un panier de chocolats spécialement préparés pour vous, professeur.\nLa journée est courte, mais je suis heureuse quand même.\nParce que des rendez-vous comme celui-ci, je sais qu'on en aura d'autres.\n\n<color=#ffd34c>Mettez-vos mains comme ceci... et voilà, ça fait un cœur ! Il est joli, j'espère que je pourrai le remplir...</color>"
