L24_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA@AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA_LOBBY_TOUCH_NORMAL_1"
L25_1 = "As long as you maintain the minimum performance, you won't be kicked out of Official Support. However, most people, including me, try harder than others so we can be recruited into an official TASKFORCE."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA@AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA_LOBBY_TOUCH_NORMAL_2"
L26_1 = "Oh, I always have my hair up. It gets in the way during battles. But my seniors seem to fight just as well and don't mind it that much."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA@AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA_LOBBY_TOUCH_NORMAL_3"
L27_1 = "I didn't become a commander because I possessed exceptional abilities. I just didn't want to hand over the job to Irie, who thought her ice cream trap would work on C.O.s."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA@AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA_LOBBY_TOUCH_NORMAL_4"
L28_1 = "Oh, this? It's not a sword that can fire sword beams, but it's made of high-quality materials. You'll realize how useful this is compared to an ordinary sword's blade dulls after attempting to cut through a C.O.'s armor."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA@AB_UI_UNIT_VOICE_NKM_UNIT_C_CIVIL_ZENA_LOBBY_TOUCH_LIFETIME_1"
L29_1 = "I'm used to getting bashed all the time. I have to be, or else it'll be hard to endure what comes next. But still, it's nice to know that you have my back, Boss."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
