L41_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_EMBLEM_BIRTHDAY"
L42_1 = "Un gâteau préparé en secret par les employés pour l'anniversaire de leur patron.\nTout le monde a contribué, mais c'est à lui de deviner qui a été le plus généreux..."
L40_1[1] = L41_1
