L2_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_CONNECT"
L3_1 = "Oh, you're here. I was making carrot salad. Do you want to try some? Hmm. You shouldn't be too picky."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_CONNECT_LIFETIME"
L4_1 = "I was looking around the company. I saw some familiar faces. Guess your reputation is better than I thought, huh?"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_NORMAL_1"
L5_1 = "Do not think I like carrots just because I'm a bunny. I preferred vegetables over meat, even before my awakening. Fu fuu, the gym rat Commander would frown whenever she saw me eat."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_NORMAL_2"
L6_1 = "I inherited the name Swift from Commander Lionel when I was young. He used to rally and lead Bygones, including myself. He was like a father to my compatriots and me."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_NORMAL_3"
L7_1 = "I'm sorry, but could you not stare at my ears like that? It's embarrassing because my ears unconsciously perk up whenever I hear something."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_NORMAL_4"
L8_1 = "I saw that someone named Lee Sooyeon is the Vice President of this company. Is that... the same Lee Sooyeon that I know? It is? Oh, I couldn't tell. She's become a lot more mature."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_LIFETIME_1"
L9_1 = "Bunny girl? So, you're into that kind of stuff. No wonder the Administration's official PR uniform is a bunny girl outfit. Hmm, but I won't need that headband. Having four giant ears would look weird, don't you think?"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_LIFETIME_2"
L10_1 = "So much has changed. Things that were kept secret before are now common knowledge. My Bygone compatriots no longer have to hide themselves. How interesting."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_LIFETIME_3"
L11_1 = "I heard that Justine struggled alone while I was frozen. I'm still the same while she grew up to become an adult. Fu fuu, I wonder what Alice would've thought if she saw Justine now."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
