L2_1 = "SI_PF_EPISODE_EVENT_INFO_FRONTBAY_TEXT"
L3_1 = "<color=#ffcf3b>Jetons de prime</color>,\naccessibles pendant l'épisode d'événement [Abandonnez le navire],\néchangeables contre différents articles."
L1_1[1] = L2_1
