L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_LIMITBREAK_3_DESC_VER3"
L38_1 = "Les employés peuvent bénéficier d'une <COLOR=#FFBC00>fusion de limites</COLOR> au prix de noyaux de fusion, de fragments de noyaux de fusion, ou de noyaux de fusion-S.\nLa <COLOR=#FFBC00>fusion de limites</COLOR> augmente <COLOR=#FFBC00>le niveau max. de 2</COLOR> et <COLOR=#FFBC00>le taux de croissance des stats de 2 %</COLOR> chaque fois qu'elle est effectuée.\nLes <COLOR=#FFBC00>fusions de limites</COLOR> peuvent être effectuées <COLOR=#FFBC00>jusqu'à 10 fois</COLOR>."
