L24_1 = {}
L25_1 = "SI_SKILL_DESC_OPR_DAIN_PR"
L26_1 = "Confère <color=#ffd34c>Infaillibilité◇</color> aux <color=#ffd34c>rangers et snipers alliés</color> pendant <color=#ffd34c>{time} s</color>. Cet effet <color=#ffd34c>ne peut pas être annulé</color>"
