L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_UNIT_SKILL_DESC_ACADEMY_CA_TWINTAIL_HYPER_LV1"
L36_1 = "Invoque une arme gigantesque cachée, infligeant des dégâts de zone dans la direction où les ennemis sont les plus nombreux. Crée une zone à l'avant qui inflige AMP DGT +20 % aux ennemis pendant 15 s."
