L25_1 = "I'm hungry. Hurry up and take me to the Counters, human."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_C_MIMIC@AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_C_MIMIC_LOBBY_CONNECT_LIFETIME"
L26_1 = "Keeheehee! What are we gonna do for fun today? Give me something tasty again!"
