L24_1[2] = L26_1
L25_1 = {}
L26_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_C_MIMIC@AB_UI_UNIT_VOICE_NKM_UNIT_CORRUPTED_C_MIMIC_LOBBY_TOUCH_NORMAL_1"
L27_1 = "There are plenty of humans who hate their own kind. I'm talking about criminals. You don't like them either, right? Let me take their power! Then I'll wipe them all out."
