L4_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BAR_S_BARTENDER_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BAR_S_BARTENDER_PR_LOBBY_CONNECT_LIFETIME"
L5_1 = "Welcome... Oh, it's you. Seriously, you almost had me fooled! Ordering alcohol in the middle of a sacred mission. Seriously?"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BAR_S_BARTENDER_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BAR_S_BARTENDER_PR_LOBBY_TOUCH_NORMAL_1"
L6_1 = "It's fine. There's no problem with you knowing that I'm with the Holy Curia. Ah, no, wait! I'm not going to torture you or do anything scary just to keep you quiet!"
