L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_SKILL_DESC_OPR_MITCH1"
L36_1 = "Confère un bonus de <color=#ffd34c>Renvoi de DGT 33 %</color> à <color=#ffd34c>tous les attaquants alliés</color> pendant <color=#ffd34c>{time} s</color>. Cette valeur s'applique à hauteur de <color=#ffd34c>66 %</color> pour les <color=#ffd34c>attaquants avec 4 ressources de déploiement ou plus</color>. Cet effet <color=#ffd34c>ne peut pas être annulé</color>. "
L34_1[1] = L35_1
L34_1[2] = L36_1
