L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_CONNECT_LIFETIME"
L14_1 = "Boss! What should we start with today? Neighborhood patrol? Organizing supplies...? Just say the word!"
