L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_INTERN_LOBBY_TOUCH_NORMAL_1"
L15_1 = "Hehehe! I'm not just Noelle anymore. I'm Super Elite Rookie Squad Member Noelle... or just Super Noelle for short! Whatever it is, leave it to me! I'll take care of it super quickly! Hup!"
L13_1[1] = L14_1
