L19_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_TOUCH_NORMAL_1"
L20_1 = "The guests' gazes are sharp... I'm used to it, but I worry they may trouble you. Even so, I won't let go of your hand. I've become... a bit greedy, you see…"
L18_1[1] = L19_1
L18_1[2] = L20_1
