L20_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_TOUCH_NORMAL_2"
L21_1 = "In Swan Lake, one ballerina plays both Odette and Odile. This dress was designed after the Black Swan. That's because it's closer to the reflection of my true heart..."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_TOUCH_NORMAL_3"
L22_1 = "They say that even the most miraculous of chances is bound to happen if it's meant to be. So this oath, forged across countless worlds, will surely lead to a happy ending."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_TOUCH_NORMAL_4"
L23_1 = "An ordinary audience would search for hints and foreshadowings they missed at a surprise ending... But as expected, you're different. Your boldness always makes my heart race, darling."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_SIXWING_CA_ACTOR_LOBBY_TOUCH_LIFETIME_1"
L24_1 = "An actor must remain graceful at all times, no matter the place. But as your partner, not a performer, perhaps it’s all right to let my guard down just a little. So if it’s a kiss to seal our vow, then I wouldn’t mind at all..."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
