L36_1 = "SI_UNIT_SKILL_NAME_ZODIAC_CA_CHARLOTTE_PASSIVE"
L37_1 = "Grace d'Astrée"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_UNIT_SKILL_DESC_ZODIAC_CA_CHARLOTTE_PASSIVE_LV1"
L38_1 = "Les dégâts de toutes les attaques augmentent proportionnellement aux PV max. Le nombre de déploiements est limité à 1 fois par combat. Si les PV chutent à 1 % ou moins, inflige des dégâts de zone de compétence ultime à l'avant et devient insensible aux dégâts pendant 4 s. Pendant la durée de l'effet, ne peut pas effectuer d'attaque de base ni de compétence, et devient insensible aux effets d'augmentation et de réduction de la VIT ATQ. Une fois la durée écoulée, récupère 50 % de ses PV max et reprend le combat."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
