L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_1_1"
L33_1 = "Les sinistres sont impartiaux. Ils touchent aussi bien ceux qui sont partis que ceux qui sont restés."
