L35_1 = "Un cauchemar qui se répète jour après jour. Quand pourrais-je me réveiller ?"
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_2"
L36_1 = "Les employés qui quittent l'Administration doivent subir une procédure d'effacement de tous leurs souvenirs qui y sont liés. Cette mesure est aussi bien destinée à protéger l’Administration que les personnes concernées des éventuelles répercussions liées à ces souvenirs."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
