L37_1 = "Chercheur en sinistre"
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_1_3"
L38_1 = "Tout comme certains poisons peuvent sauver des vies, la Corruption aussi, si elle est étudiée, finira un jour par démontrer son utilité. Malgré tout, un poison reste un poison."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_3"
L39_1 = "Se cacher les yeux est un symbole de mystère. Tout comme les masques, les cache-œils et les franges."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
