L40_1 = "Ne pas utiliser sauf en cas de nécessité absolue"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP14_1_4"
L41_1 = "Un grand pouvoir vient toujours avec un prix à payer. Ce prix peut varier mais nul n’y échappe."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP14_ACT1_INTERLUDE_4"
L42_1 = "Elle fend l’espace avec son épée. Mais cette capacité ne se limite pas à trancher les ennemis, en effet, selon son niveau de maîtrise, elle permet aussi de dissimuler des objets et de déplacer des personnes."
L40_1[1] = L41_1
