L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE@AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE_LOBBY_CONNECT_LIFETIME"
L38_1 = "Ah, perfect timing. I was just gathering samples to investigate an unusual Corruption environment... But if you're tired, do take a break. I'll ask Andy instead."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE@AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE_LOBBY_TOUCH_NORMAL_1"
L39_1 = "All things are in flux, so nothing holds a fixed form. Which is to say, today's me differs from yesterday's. Rather like quantum uncertainty, wouldn't you agree?"
