L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_UNIT_SKILL_DESC_ESPR_CA_KNIGHT_PASSIVE2_LV1"
L21_1 = "Toutes les 3 attaques de base, effectue une attaque améliorée. L'attaque améliorée inflige des dégâts de zone à l'avant. Lorsqu'un ennemi meurt, l'attaque de base suivante est remplacée par une attaque améliorée. Le nombre de remplacements possibles s’accumule, et le compteur est réduit de 1 lors de l'activation. L'attaque améliorée utilisée en remplacement inflige des dégâts de zone à la cible et autour et inflige Entrave◇ pendant 3 s. Toutes les attaques améliorées sont systématiquement CRIT."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
