L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_NORMAL_1"
L36_1 = "Burnett... You still remember that name, Old Voice. But the man who bore it is long dead. I am the Knight of the Lake, Apostle of Mother Gha'agsheblah, guardian of the Lake of Knowledge."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_NORMAL_2"
L37_1 = "The Children of Yaldabaoth are a congregation gathered for Mother's manifestation. When the shattered Lake of Knowledge is made whole and the aimless Society cast aside, our sacred purpose will finally be fulfilled."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_NORMAL_3"
L38_1 = "Reborn under the Lake's blessing, I serve only Mother Gha'agsheblah's essence. Should you stand against her will, the Institution, the Society, and even you, Old Voice, are my enemies."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
