L39_1 = "In fragments of my memory, the daughter of the House Pendragon was smaller, more fragile. Yet the Pendragon of this world has grown into quite the bold young woman. Heh. How nostalgic."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_LIFETIME_1"
L40_1 = "The Society has endured through countless names and forms. Yet now that it has abandoned its devotion to the Lake and lives only to serve one person, the Lake's blessing will surely side with us."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
