L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_TITLE_SS_OMEN_4"
L7_1 = "Présage"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_NAME_SS_OMEN_4"
L8_1 = "Dérive"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_DESC_1_SS_OMEN_4"
L9_1 = "La mer se teinte d'un noir si profond qu’on ne peut voir à un pas devant soi.\nUne jeune fille qui navigue sans destination, un capitaine hésitant dans ses choix, et ceux qui rament pour leur propre avenir."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_PROLOGUE"
L10_1 = "Il y a 20 ans, Front Bay était un territoire hostile où l’on s’entretuait pour survivre.\nMais quelqu’un apporta l’ordre à ces gens-là.\nLes gens l’appelaient le Grand Pirate."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE1"
L11_1 = "Naviguer sans cap, c'est devenir une une proie facile pour la mer."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE2"
L12_1 = "Les conditions pour transférer un prisonnier sur un autre navire étaient plutôt strictes.\nPremièrement, il fallait être une personne ayant déjà perçu des primes à Front Bay pendant une certaine période.\nDeuxièmement, être une TASKFORCE officiellement autorisée.\nTroisièmement, être un pirate."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_4_1_1"
L13_1 = "Pirate"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_1_1"
L14_1 = "Pourquoi suis-je devenue pirate ? C'est très simple.\nLe lever de soleil vu du bord de la falaise de l'île Macha était carrément romantique."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE3"
L15_1 = "Les Opérateurs de l’Ancienne Administration n’étaient pas de simples IA exécutant un rôle prédéfini.\nIls étaient des individus dotés d’émotions, capables de parler avec les gens, de rire, de s’attrister et d’éprouver de l’empathie."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE4"
L16_1 = "Ses talents étaient inhumains, c’est pourquoi on la qualifiait de monstre.\nSes talents étaient inhumains, c’est pourquoi on la qualifiait de fée.\nPeu importe ce que les gens pouvaient penser d’elle, son souhait demeurait toujours le même.\nPour un monde meilleur."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_4_1_2"
L17_1 = "Pays natal"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_1_2"
L18_1 = "Le lieu où l’on est né et où l’on a grandi.\nLà où ont vécu nos ancêtres de génération en génération.\nCe lieu familier et chéri que l’on garde profondément en son cœur."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE5"
L19_1 = "Parfois, les gens risquent leur vie pour des raisons dépourvues de logique.\nPar exemple, parce qu’ils veulent montrer aux autres le lever de soleil qui annonce demain."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE6"
L20_1 = "Le Counter officiel de Front Bay n’apparaît jamais en public.\nCertains supposent qu’il est mort lors du Déluge noir survenu il y a 10 ans, mais l’Administration n’a jamais donné la moindre réponse."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_4_1_3"
L21_1 = "Prédateur"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_1_3"
L22_1 = "Le prédateur ne fait pas de distinction entre ses proies.\nIl ne fait que dévorer."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE7"
L23_1 = "Parce que quelqu’un... espérera que tu vives."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE8"
L24_1 = "Pour révéler la vérité de ce jour-là, il a fallu une longue préparation intérieure.\nCar chaque fois qu'elle regardait le visage de cette enfant, elle devait se rappeler d’elle, souriant dos au ciel rouge du crépuscule."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE9"
L25_1 = "La volonté et les rêves des gens ne peuvent être arrêtés, pas même par la mort."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE10"
L26_1 = "Ils nous atteignent toujours, au-delà de la mort."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_4_1_4"
L27_1 = "Dernière chasse"
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_1_4"
L28_1 = "Le Grand Pirate Avery disait :\nQue le passé n'était pas important pour les pirates qui vivent dans le présent.\nAu lieu de parler de son passé, il laissa sa marque en cachant des trésors aux quatre coins du monde.\nPour que les générations futures puissent surmonter les épreuves qui les attendent."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_4_1_5"
L29_1 = "Avènement"
