L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_1_5"
L30_1 = "■■ tendit la main au-dessus de la mer. ■■ repoussa les eaux toute la nuit à l'aide d'un violent vent d’est, transformant la mer en terre sèche.\nEt lorsque les eaux se fendirent, les descendants d'■■■■ s'avancèrent au milieu de la mer, sur la terre sèche.\nL’eau formait un mur à leur gauche et à leur droite."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_EPILOGUE"
L31_1 = "Pour que le passé puisse parvenir jusqu’à aujourd’hui."
