L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_PROLOGUE"
L10_1 = "À l'époque de la Coalition Internationale, Richard Werner a risqué sa vie pour protéger Charade.\nAvec le temps, il a fini par devenir un Senior, et il est resté dévoué à cette ville."
L8_1[1] = L9_1
