L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_INTERLUDE1"
L11_1 = "Dans chaque ville, la condition minimale pour être reconnu Counter officiel est d'être de rang S.\nBien entendu, il ne s'agit là que du strict minimum."
L9_1[1] = L10_1
