L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_2"
L15_1 = "Un chien de chasse poursuit sa proie pour son maître.\nUn chien de combat se bat contre les autres chiens pour son maître.\nMais nul ne peut savoir pour quelle raison un chien enragé montre les crocs."
L13_1[1] = L14_1
L13_1[2] = L15_1
