L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RAT_LOBBY_CAPTAIN"
L16_1 = "Fine. Mind if I take a look around your office? I'm curious how many cute Artifacts you've been hoarding."
