L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_OPR_DOGABI@AB_UI_UNIT_VOICE_OPR_DOGABI_LOBBY_TOUCH_LIFETIME_3"
L36_1 = "The Three Blades... What a name that brings me back. Back then, I lived for the pride of it all. Hmm... If I have one regret, it's never telling that woman of the Three Blades how I felt. Well I guess that's fate too."
L34_1[1] = L35_1
L34_1[2] = L36_1
