L42_1 = "SI_UNIT_SKILL_DESC_ESPR_C_SWORD_SKILL_LV1"
L43_1 = "Inflige des dégâts de zone à l'avant. Les cibles touchées subissent Étourdissement◇ pendant 2 s, et si la cible est un Attaquant, subit Étourdissement◇ pendant 4 s."
L41_1[1] = L42_1
L41_1[2] = L43_1
