L42_1 = {}
L43_1 = "SI_EXPLORE_EVENT_RESULTDESC2_80065_1"
L44_1 = "Le dragon démoniaque pousse un cri strident, comme s'il avait totalement oublié qui vous étiez.\nCalmement, vous ordonnez le saut dimensionnel.\nCar pour l'heure, il n'existe aucun moyen de l'apaiser."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
