L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_2"
L5_1 = "Un monde où la mort n'a plus de sens, un monde où les rêves deviennent réalité. Cette âme blessée, prisonnière des remparts du paradis, se teinte de paix et de sécurité."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_3"
L6_1 = "L'arbre doré est immuable. Même le temps y demeure immobile. Ceux qui s'avancent vers l'avenir ne sont pas dignes d'y faire face."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_4"
L7_1 = "Un lance-pierres projette d'autant plus loin que son élastique est long, et une toupie tourne d'autant plus longtemps que sa ficelle est longue. Il en va de même pour une machine à remonter le temps."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_5"
L8_1 = "À la fin de l'automne, arrêtée dans le temps, à la veille de l'hiver, la jeune fille devient un arbre doré solitaire et, par sa propre mort, empêche d'accéder au lendemain."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_6"
